a.contour(pH,E,idx,levels=np.arange(len(u))+0.5,colors='tab:orange',linewidths=1.5)
labf=d['labFe']; uf=sorted(set(labf.ravel())); idf=np.array([[uf.index(x) for x in r] for r in labf])
