for k,n in enumerate(u):
    m=idx==k; a.text(pH[m.any(0)].mean(),E[m.any(1)].mean(),n,color='darkred',ha='center',fontsize=8)
for k,n in enumerate(uf):
    m=idf==k; a.text(pH[m.any(0)].mean(),E[m.any(1)].mean()-0.05,n,color='navy',ha='center',fontsize=8)
a.plot(pH,1.229-0.0592*pH,'k:',lw=1); a.plot(pH,-0.0592*pH,'k:',lw=1)
a.set_xlabel('pH'); a.set_ylabel('E / V vs SHE'); a.set_title('Joint Cu (orange, solid) + Fe (blue, dashed) predominance boundaries')
